package com.bookstore.controller; import com.bookstore.repository.CustomerRepository; import com.bookstore.service.*; import org.junit.jupiter.api.Test; import org.springframework.ui.ConcurrentModel; import java.math.BigDecimal; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*; class HomeControllerTest{@Test void dashboardAddsMetrics(){BookService b=mock(BookService.class);CustomerRepository c=mock(CustomerRepository.class);OrderService o=mock(OrderService.class);when(b.count()).thenReturn(2L);when(c.count()).thenReturn(3L);when(o.count()).thenReturn(4L);when(o.totalSales()).thenReturn(BigDecimal.TEN);ConcurrentModel m=new ConcurrentModel();assertEquals("dashboard",new HomeController(b,c,o).dashboard(m));assertEquals(2L,m.get("bookCount"));}}